function extractPromptFromFlowResponse(rawText) {
  if (!rawText || typeof rawText !== 'string') return null;
  const clean = rawText.replace(/^\)\]\}'/, '').trim();
  const candidates = [];
  function walk(item) {
    if (!item) return;
    if (typeof item === 'string') {
      const s = item.trim();
      if ((s.startsWith('[') && s.endsWith(']')) || (s.startsWith('{') && s.endsWith('}'))) {
        try {
          const parsed = JSON.parse(s);
          walk(parsed);
          return;
        } catch(e) {}
      }
      if (s.length > 30 && !s.startsWith('http://') && !s.startsWith('https://') && !s.startsWith('boq_labs')) {
        candidates.push(s);
      }
      return;
    }
    if (Array.isArray(item)) {
      for (const el of item) walk(el);
      return;
    }
    if (typeof item === 'object') {
      for (const k of Object.keys(item)) walk(item[k]);
    }
  }

  const lines = clean.split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || /^\d+$/.test(trimmed)) continue;
    try {
      const parsed = JSON.parse(trimmed);
      walk(parsed);
    } catch(e) {}
  }

  if (candidates.length > 0) {
    const keywords = ['camera', 'shot', 'woman', 'smile', 'dress', 'fabric', 'walk', 'movement', 'motion', 'cinematic', 'mouth', 'pose', 'scene', 'soundscape'];
    candidates.sort((a, b) => {
      const scoreA = keywords.reduce((acc, kw) => acc + (a.toLowerCase().includes(kw) ? 1 : 0), 0);
      const scoreB = keywords.reduce((acc, kw) => acc + (b.toLowerCase().includes(kw) ? 1 : 0), 0);
      if (scoreA !== scoreB) return scoreB - scoreA;
      return b.length - a.length;
    });
    return candidates[0].replace(/\\n/g, ' ').replace(/\\"/g, '"').trim();
  }
  return null;
}

